import { getErrorMessage } from "@workspace/utils"

import { BotifyToolingError } from "../lib/errors"
import { writeFileIfChanged } from "../lib/fs-utils"
import type {
  GenerateRouteTypesOptions,
  RouteTypegenCounts,
  RouteTypegenFile,
  WriteRouteTypesOptions,
  WriteRouteTypesResult,
} from "../types/codegen.types"

const DEFAULT_BANNER = [
  "// This file is auto-generated by @use-botify/tooling.",
  "// Do not edit manually; re-run route typegen after changing files in features/.",
].join("\n")

const PARAM_SEGMENT_PATTERN =
  /^(?:\[([A-Za-z_][A-Za-z0-9_]*)\]|\{([A-Za-z_][A-Za-z0-9_]*)\})$/

function sortUnique(values: Iterable<string>): string[] {
  return [...new Set(values)].sort((a, b) => a.localeCompare(b))
}

function formatStringUnion(values: readonly string[]): string {
  if (values.length === 0) {
    return "never"
  }

  if (values.length === 1 && values[0] !== undefined) {
    return JSON.stringify(values[0])
  }

  return `\n${values.map((value) => `  | ${JSON.stringify(value)}`).join("\n")}`
}

function extractCallbackParamNames(pattern: string): string[] {
  const params: string[] = []

  for (const segment of pattern.split(":")) {
    const match = PARAM_SEGMENT_PATTERN.exec(segment)
    const name = match?.[1] ?? match?.[2]
    if (name) {
      params.push(name)
    }
  }

  return params
}

function formatCallbackParamsEntry(pattern: string): string {
  const params = extractCallbackParamNames(pattern)

  if (params.length === 0) {
    return `  readonly ${JSON.stringify(pattern)}: Readonly<Record<string, never>>`
  }

  const fields = params.map((param) => `readonly ${param}: string`).join("; ")

  return `  readonly ${JSON.stringify(pattern)}: { ${fields} }`
}

function collectCounts(files: readonly RouteTypegenFile[]): RouteTypegenCounts {
  const features = new Set<string>()
  const commands = new Set<string>()
  const callbacks = new Set<string>()

  for (const file of files) {
    features.add(file.featureName)
    if (file.kind === "command" && file.commandName) {
      commands.add(file.commandName)
    }
    if (file.kind === "callback" && file.callbackPattern) {
      callbacks.add(file.callbackPattern)
    }
  }

  return Object.freeze({
    features: features.size,
    commands: commands.size,
    callbacks: callbacks.size,
  })
}

/**
 * Generates deterministic TypeScript route declarations from discovered
 * `features/` file descriptors.
 */
export function generateRouteTypes(
  files: readonly RouteTypegenFile[],
  options: GenerateRouteTypesOptions = {}
): string {
  const banner = options.banner ?? DEFAULT_BANNER

  const featureNames = sortUnique(files.map((file) => file.featureName))
  const accessTiers = sortUnique(files.map((file) => file.access))
  const commandNames = sortUnique(
    files.flatMap((file) =>
      file.kind === "command" && file.commandName ? [file.commandName] : []
    )
  )
  const callbackPatterns = sortUnique(
    files.flatMap((file) =>
      file.kind === "callback" && file.callbackPattern
        ? [file.callbackPattern]
        : []
    )
  )

  const paramsMapBody =
    callbackPatterns.length > 0
      ? `\n${callbackPatterns.map(formatCallbackParamsEntry).join("\n")}\n`
      : ""

  return [
    banner,
    "",
    `export type BotifyFeatureName = ${formatStringUnion(featureNames)}`,
    "",
    `export type BotifyAccessTier = ${formatStringUnion(accessTiers)}`,
    "",
    `export type BotifyCommandName = ${formatStringUnion(commandNames)}`,
    "",
    `export type BotifyCallbackPattern = ${formatStringUnion(callbackPatterns)}`,
    "",
    `export interface BotifyCallbackParamsMap {${paramsMapBody}}`,
    "",
    "export type BotifyCallbackParams<P extends BotifyCallbackPattern = BotifyCallbackPattern> =",
    "  P extends keyof BotifyCallbackParamsMap ? BotifyCallbackParamsMap[P] : never",
    "",
  ].join("\n")
}

/**
 * Scans `featuresDir` using `@use-botify/router/fs` and writes the generated
 * route declarations to `outputPath` only when content changes.
 */
export async function writeRouteTypes(
  options: WriteRouteTypesOptions
): Promise<WriteRouteTypesResult> {
  const logger = options.logger === false ? undefined : options.logger

  let discoverRoutes: typeof import("@use-botify/router/fs").discoverRoutes

  try {
    const routerFs = await import("@use-botify/router/fs")
    discoverRoutes = routerFs.discoverRoutes
  } catch (error: unknown) {
    throw new BotifyToolingError(
      "CODEGEN_FAILED",
      `writeRouteTypes() requires "@use-botify/router" to be installed: ${getErrorMessage(error)}`,
      { cause: error }
    )
  }

  let files: readonly RouteTypegenFile[]

  try {
    files = await discoverRoutes({
      featuresDir: options.featuresDir,
      defaultAccess: options.defaultAccess,
      extensions: options.extensions,
    })
  } catch (error: unknown) {
    throw new BotifyToolingError(
      "CODEGEN_FAILED",
      `Failed to discover routes in "${options.featuresDir}": ${getErrorMessage(error)}`,
      { cause: error }
    )
  }

  const content = generateRouteTypes(files, { banner: options.banner })
  const counts = collectCounts(files)
  const writeResult = await writeFileIfChanged(options.outputPath, content)

  logger?.info(
    "RouteTypegen",
    writeResult.written
      ? "Updated generated route types"
      : "Generated route types already up to date",
    {
      outputPath: writeResult.filePath,
      ...counts,
    }
  )

  return Object.freeze<WriteRouteTypesResult>({
    ...writeResult,
    counts,
  })
}
